import * as React from 'react'
import { cn } from '@/lib/utils'
import { ChevronDownIcon, ChevronLeftIcon, ChevronRightIcon } from 'lucide-react'
import { DayPicker, getDefaultClassNames, type DayButton } from 'react-day-picker'

import { Button, buttonVariants } from '@/components/ui/button'
import { useUIConfig } from '@/components/ui/config-provider'
import { getDateLocale } from '@/lib/date-adapter'

function Calendar({
  className,
  classNames,
  showOutsideDays = true,
  captionLayout = 'label',
  buttonVariant = 'ghost',
  formatters,
  components,
  ...props
}: React.ComponentProps<typeof DayPicker> & {
  buttonVariant?: React.ComponentProps<typeof Button>['variant']
}) {
  const defaultClassNames = getDefaultClassNames()
  const config = useUIConfig()

  return (
    <DayPicker
      locale={getDateLocale(config.locale)}
      showOutsideDays={showOutsideDays}
      className={cn(
        'group/calendar bg-background p-3 [--cell-size:--spacing(8)] [[data-slot=card-content]_&]:bg-transparent [[data-slot=popover-content]_&]:bg-transparent',
        String.raw`rtl:**:[.rdp-button\_next>svg]:rotate-180`,
        String.raw`rtl:**:[.rdp-button\_previous>svg]:rotate-180`,
        className,
      )}
      captionLayout={captionLayout}
      formatters={{
        formatMonthDropdown: (date) => date.toLocaleString(config.locale, { month: 'short' }),
        ...formatters,
      }}
      classNames={{
        root: cn('w-fit', defaultClassNames.root),
        months: cn('relative flex flex-col gap-4 md:flex-row', defaultClassNames.months),
        month: cn('flex w-full flex-col gap-4', defaultClassNames.month),
        nav: cn(
          'absolute inset-x-0 top-0 flex w-full items-center justify-between gap-1',
          defaultClassNames.nav,
        ),
        button_previous: cn(
          buttonVariants({ variant: buttonVariant }),
          'size-(--cell-size) p-0 select-none aria-disabled:opacity-50',
          defaultClassNames.button_previous,
        ),
        button_next: cn(
          buttonVariants({ variant: buttonVariant }),
          'size-(--cell-size) p-0 select-none aria-disabled:opacity-50',
          defaultClassNames.button_next,
        ),
        month_caption: cn(
          'flex h-(--cell-size) w-full items-center justify-center px-(--cell-size)',
          defaultClassNames.month_caption,
        ),
        dropdowns: cn(
          'flex h-(--cell-size) w-full items-center justify-center gap-1.5 text-sm font-medium',
          defaultClassNames.dropdowns,
        ),
        dropdown_root: cn(
          'relative rounded-md border border-input shadow-xs has-focus:border-ring has-focus:ring-[3px] has-focus:ring-ring/50',
          defaultClassNames.dropdown_root,
        ),
        dropdown: cn('absolute inset-0 bg-popover opacity-0', defaultClassNames.dropdown),
        caption_label: cn(
          'font-medium select-none',
          captionLayout === 'label'
            ? 'text-sm'
            : 'flex h-8 items-center gap-1 rounded-md pr-1 pl-2 text-sm [&>svg]:size-3.5 [&>svg]:text-muted-foreground',
          defaultClassNames.caption_label,
        ),
        month_grid: cn('w-full border-collapse', defaultClassNames.month_grid),
        weekdays: cn('flex', defaultClassNames.weekdays),
        weekday: cn(
          'flex-1 rounded-md text-[0.8rem] font-normal text-muted-foreground select-none',
          defaultClassNames.weekday,
        ),
        week: cn('mt-2 flex w-full', defaultClassNames.week),
        week_number_header: cn('w-(--cell-size) select-none', defaultClassNames.week_number_header),
        week_number: cn(
          'text-[0.8rem] text-muted-foreground select-none',
          defaultClassNames.week_number,
        ),
        day: cn(
          'group/day relative aspect-square h-full w-full p-0 text-center select-none [&:last-child[data-selected=true]_button]:rounded-r-md',
          props.showWeekNumber
            ? '[&:nth-child(2)[data-selected=true]_button]:rounded-l-md'
            : '[&:first-child[data-selected=true]_button]:rounded-l-md',
          defaultClassNames.day,
        ),
        range_start: cn('rounded-l-md bg-accent', defaultClassNames.range_start),
        range_middle: cn('rounded-none', defaultClassNames.range_middle),
        range_end: cn('rounded-r-md bg-accent', defaultClassNames.range_end),
        today: cn(
          'rounded-md bg-accent text-accent-foreground data-[selected=true]:rounded-none',
          defaultClassNames.today,
        ),
        outside: cn(
          'text-muted-foreground aria-selected:text-muted-foreground',
          defaultClassNames.outside,
        ),
        disabled: cn('text-muted-foreground opacity-50', defaultClassNames.disabled),
        hidden: cn('invisible', defaultClassNames.hidden),
        ...classNames,
      }}
      components={{
        Root: ({ className, rootRef, ...props }) => {
          return <div data-slot="calendar" ref={rootRef} className={cn(className)} {...props} />
        },
        Chevron: ({ className, orientation, ...props }) => {
          if (orientation === 'left') {
            return <ChevronLeftIcon className={cn('size-4', className)} {...props} />
          }

          if (orientation === 'right') {
            return <ChevronRightIcon className={cn('size-4', className)} {...props} />
          }

          return <ChevronDownIcon className={cn('size-4', className)} {...props} />
        },
        DayButton: CalendarDayButton,
        WeekNumber: ({ children, ...props }) => {
          return (
            <td {...props}>
              <div className="flex size-(--cell-size) items-center justify-center text-center">
                {children}
              </div>
            </td>
          )
        },
        ...components,
      }}
      {...props}
    />
  )
}

function CalendarDayButton({
  className,
  day,
  modifiers,
  ...props
}: React.ComponentProps<typeof DayButton>) {
  const defaultClassNames = getDefaultClassNames()

  const ref = React.useRef<HTMLButtonElement>(null)
  React.useEffect(() => {
    if (modifiers.focused) ref.current?.focus()
  }, [modifiers.focused])

  return (
    <Button
      ref={ref}
      variant="ghost"
      size="icon"
      data-day={day.date.toLocaleDateString()}
      data-selected-single={
        modifiers.selected &&
        !modifiers.range_start &&
        !modifiers.range_end &&
        !modifiers.range_middle
      }
      data-range-start={modifiers.range_start}
      data-range-end={modifiers.range_end}
      data-range-middle={modifiers.range_middle}
      className={cn(
        'flex aspect-square size-auto w-full min-w-(--cell-size) flex-col gap-1 leading-none font-normal group-data-[focused=true]/day:relative group-data-[focused=true]/day:z-10 group-data-[focused=true]/day:border-ring group-data-[focused=true]/day:ring-[3px] group-data-[focused=true]/day:ring-ring/50 data-[range-end=true]:rounded-md data-[range-end=true]:rounded-r-md data-[range-end=true]:bg-primary data-[range-end=true]:text-primary-foreground data-[range-middle=true]:rounded-none data-[range-middle=true]:bg-accent data-[range-middle=true]:text-accent-foreground data-[range-start=true]:rounded-md data-[range-start=true]:rounded-l-md data-[range-start=true]:bg-primary data-[range-start=true]:text-primary-foreground data-[selected-single=true]:bg-primary data-[selected-single=true]:text-primary-foreground dark:hover:text-accent-foreground [&>span]:text-xs [&>span]:opacity-70',
        defaultClassNames.day,
        className,
      )}
      {...props}
    />
  )
}

export { Calendar, CalendarDayButton }

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'
import { Slot } from 'radix-ui'
import { Loader2 } from 'lucide-react'

const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground hover:bg-primary/90',
        destructive:
          'bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40',
        outline:
          'border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50',
        secondary: 'bg-secondary text-secondary-foreground hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50',
        link: 'text-primary underline-offset-4 hover:underline',
        soft: 'bg-primary/10 text-primary hover:bg-primary/15',
        success: 'bg-emerald-600 text-white hover:bg-emerald-700',
        warning: 'bg-amber-400 text-amber-950 hover:bg-amber-500',
        dashed:
          'border border-dashed bg-background text-foreground hover:border-primary hover:text-primary',
      },
      size: {
        default: 'h-9 px-4 py-2 has-[>svg]:px-3',
        xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: 'h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5',
        lg: 'h-10 rounded-md px-6 has-[>svg]:px-4',
        icon: 'size-9',
        'icon-xs': "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        'icon-sm': 'size-8',
        'icon-lg': 'size-10',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
)

function Button({
  className,
  variant = 'default',
  size = 'default',
  asChild = false,
  loading = false,
  children,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
    loading?: boolean
  }) {
  const Comp = asChild ? Slot.Root : 'button'

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(
        buttonVariants({ variant, size }),
        size === 'default' && '[[data-density=compact]_&]:h-[30px] [[data-density=compact]_&]:py-1',
        className,
      )}
      aria-busy={loading || undefined}
      {...props}
      disabled={props.disabled || loading}
    >
      {asChild ? (
        children
      ) : (
        <>
          {loading && <Loader2 className="animate-spin" />}
          {children}
        </>
      )}
    </Comp>
  )
}

export { Button, buttonVariants }

import { contrastForeground } from '@/lib/contrast'
import * as React from 'react'
import { cn } from '@/lib/utils'
import { Direction } from 'radix-ui'
export interface UIConfig {
  density: 'comfortable' | 'compact'
  direction: 'ltr' | 'rtl'
  locale: string
}
const ConfigContext = React.createContext<UIConfig>({
  density: 'comfortable',
  direction: 'ltr',
  locale: 'en-US',
})
const PortalContext = React.createContext<HTMLElement | null>(null)
export const usePortalContainer = () => React.useContext(PortalContext) ?? undefined
export const useUIConfig = () => React.useContext(ConfigContext)
export interface ConfigProviderProps extends React.HTMLAttributes<HTMLDivElement> {
  density?: UIConfig['density']
  direction?: UIConfig['direction']
  locale?: string
  accent?: string
  radius?: number
}
export function ConfigProvider({
  density: providedDensity,
  direction: providedDirection,
  locale: providedLocale,
  accent,
  radius,
  children,
  style,
  className,
  ...props
}: ConfigProviderProps) {
  const parent = useUIConfig(),
    density = providedDensity ?? parent.density,
    direction = providedDirection ?? parent.direction,
    locale = providedLocale ?? parent.locale
  const [portal, setPortal] = React.useState<HTMLDivElement | null>(null)
  return (
    <ConfigContext.Provider value={{ density, direction, locale }}>
      <PortalContext.Provider value={portal}>
        <Direction.Provider dir={direction}>
          <div
            dir={direction}
            lang={locale}
            data-density={density}
            className={cn('ergon-root', className)}
            style={
              {
                ...(accent
                  ? {
                      '--primary': accent,
                      '--ring': accent,
                      '--primary-foreground': contrastForeground(accent),
                    }
                  : {}),
                ...(radius !== undefined ? { '--radius': `${radius}px` } : {}),
                ...style,
              } as React.CSSProperties
            }
            {...props}
          >
            {children}
            <div ref={setPortal} data-ergon-portals="" style={{ display: 'contents' }} />
          </div>
        </Direction.Provider>
      </PortalContext.Provider>
    </ConfigContext.Provider>
  )
}

import { enUS, id, de, fr, ja } from 'date-fns/locale'
export const dateLocales = { 'en-US': enUS, 'id-ID': id, 'de-DE': de, 'fr-FR': fr, 'ja-JP': ja }
export const getDateLocale = (locale: string) =>
  dateLocales[locale as keyof typeof dateLocales] ?? enUS
export function toZonedInput(date: Date, timeZone: string) {
  if (!Number.isFinite(+date)) return ''
  const parts = new Intl.DateTimeFormat('en-CA', {
      timeZone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hourCycle: 'h23',
    }).formatToParts(date),
    part = (type: string) => parts.find((p) => p.type === type)?.value
  return `${part('year')}-${part('month')}-${part('day')}T${part('hour')}:${part('minute')}:${part('second')}`
}
export function fromZonedInput(text: string, timeZone: string) {
  if (!/^\d{4}-\d\d-\d\dT\d\d:\d\d(?::\d\d)?$/.test(text))
    throw new Error('Enter a valid date and time')
  const normalized = text.length === 16 ? text + ':00' : text,
    wall = Date.parse(normalized + 'Z'),
    matches: number[] = []
  for (let offset = -36; offset <= 36; offset += 6) {
    const sample = wall + offset * 3600000,
      zoneWall = Date.parse(toZonedInput(new Date(sample), timeZone) + 'Z'),
      candidate = wall - (zoneWall - sample)
    if (toZonedInput(new Date(candidate), timeZone) === normalized) matches.push(candidate)
  }
  if (!matches.length) throw new Error('This local time does not exist in the selected time zone')
  return new Date(Math.min(...matches))
}

import * as React from 'react'
import { format, isSameDay, addDays, addMonths, startOfMonth, startOfWeek } from 'date-fns'
import { Calendar, CalendarDayButton } from '@/components/ui/calendar'
import type { DayButton } from 'react-day-picker'
import { Button } from '@/components/ui/button'
import { useUIConfig } from '@/components/ui/config-provider'
export interface CalendarEvent {
  id: string
  date: Date
  title: string
  color?: string
}
export function EventCalendar({
  events,
  value,
  onValueChange,
  mode = 'compact',
}: {
  events: CalendarEvent[]
  value?: Date
  onValueChange?: (date: Date | undefined) => void
  mode?: 'compact' | 'month' | 'year'
}) {
  const config = useUIConfig(),
    [view, setView] = React.useState(() => value ?? new Date()),
    root = React.useRef<HTMLDivElement>(null),
    start = startOfWeek(startOfMonth(view)),
    days = Array.from({ length: 42 }, (_, index) => addDays(start, index))
  const select = (date: Date) => {
    onValueChange?.(date)
  }
  const focus = (date: Date) => {
    select(date)
    if (date.getMonth() !== view.getMonth()) setView(date)
    requestAnimationFrame(() =>
      root.current
        ?.querySelector<HTMLElement>(`[data-calendar-date="${format(date, 'yyyy-MM-dd')}"]`)
        ?.focus(),
    )
  }
  if (mode === 'compact')
    return (
      <div className="space-y-4">
        <Calendar
          mode="single"
          selected={value}
          onSelect={onValueChange}
          className="mx-auto rounded-xl border"
          components={{
            DayButton: (props: React.ComponentProps<typeof DayButton>) => {
              const matches = events.filter((event) => isSameDay(event.date, props.day.date))
              return (
                <CalendarDayButton
                  {...props}
                  title={matches.map((event) => event.title).join(', ')}
                >
                  {props.children}
                  {matches.length > 0 && (
                    <span className="flex gap-0.5">
                      {matches.slice(0, 3).map((event) => (
                        <span
                          key={event.id}
                          className="size-1 rounded-full"
                          style={{ background: event.color ?? 'var(--primary)' }}
                        />
                      ))}
                    </span>
                  )}
                </CalendarDayButton>
              )
            },
          }}
        />
        {value && (
          <ul className="space-y-2">
            {events
              .filter((event) => isSameDay(event.date, value))
              .map((event) => (
                <li
                  key={event.id}
                  className="flex items-center gap-2 rounded-lg border p-3 text-sm"
                >
                  <span
                    className="size-2 rounded-full"
                    style={{ background: event.color ?? 'var(--primary)' }}
                  />
                  {event.title}
                </li>
              ))}
            {!events.some((event) => isSameDay(event.date, value)) && (
              <li className="text-center text-xs text-muted-foreground">
                No events on{' '}
                {new Intl.DateTimeFormat(config.locale, { dateStyle: 'medium' }).format(value)}.
              </li>
            )}
          </ul>
        )}
      </div>
    )
  return (
    <section className="w-full space-y-4">
      <header className="flex items-center justify-between gap-3">
        <Button
          variant="outline"
          size="sm"
          aria-label="Previous period"
          onClick={() => setView((date) => addMonths(date, mode === 'year' ? -12 : -1))}
        >
          ←
        </Button>
        <h3 className="text-sm font-semibold">
          {new Intl.DateTimeFormat(
            config.locale,
            mode === 'year' ? { year: 'numeric' } : { year: 'numeric', month: 'long' },
          ).format(view)}
        </h3>
        <Button
          variant="outline"
          size="sm"
          aria-label="Next period"
          onClick={() => setView((date) => addMonths(date, mode === 'year' ? 12 : 1))}
        >
          →
        </Button>
      </header>
      {mode === 'year' ? (
        <div className="grid gap-3 sm:grid-cols-3">
          {Array.from({ length: 12 }, (_, month) => {
            const date = new Date(view.getFullYear(), month, 1),
              matches = events.filter(
                (event) =>
                  event.date.getFullYear() === view.getFullYear() &&
                  event.date.getMonth() === month,
              )
            return (
              <button
                key={month}
                className="min-h-28 rounded-lg border p-4 text-left hover:border-primary"
                onClick={() => select(date)}
              >
                <span className="text-sm font-medium">
                  {new Intl.DateTimeFormat(config.locale, { month: 'long' }).format(date)}
                </span>
                <span className="mt-2 block text-xs text-muted-foreground">
                  {matches.length} events
                </span>
                {matches.slice(0, 2).map((event) => (
                  <span key={event.id} className="mt-1 block truncate text-[10px] text-primary">
                    {event.title}
                  </span>
                ))}
              </button>
            )
          })}
        </div>
      ) : (
        <div
          ref={root}
          role="grid"
          aria-label="Month calendar"
          className="overflow-x-auto rounded-lg border"
        >
          <div role="row" className="grid min-w-[490px] grid-cols-7">
            {days.slice(0, 7).map((day) => (
              <div
                role="columnheader"
                key={+day}
                className="border-b p-2 text-center text-xs text-muted-foreground"
              >
                {new Intl.DateTimeFormat(config.locale, { weekday: 'short' }).format(day)}
              </div>
            ))}
          </div>
          {Array.from({ length: 6 }, (_, week) => (
            <div role="row" key={week} className="grid min-w-[490px] grid-cols-7">
              {days.slice(week * 7, week * 7 + 7).map((day) => (
                <button
                  role="gridcell"
                  aria-label={new Intl.DateTimeFormat(config.locale, { dateStyle: 'full' }).format(
                    day,
                  )}
                  aria-selected={!!value && isSameDay(value, day)}
                  tabIndex={isSameDay(value ?? view, day) ? 0 : -1}
                  data-calendar-date={format(day, 'yyyy-MM-dd')}
                  key={+day}
                  onClick={() => select(day)}
                  onKeyDown={(event) => {
                    const delta: Record<string, number> = {
                      ArrowLeft: -1,
                      ArrowRight: 1,
                      ArrowUp: -7,
                      ArrowDown: 7,
                      Home: -day.getDay(),
                      End: 6 - day.getDay(),
                    }
                    if (event.key in delta) {
                      event.preventDefault()
                      focus(addDays(day, delta[event.key]))
                    }
                    if (event.key === 'PageUp' || event.key === 'PageDown') {
                      event.preventDefault()
                      focus(addMonths(day, event.key === 'PageUp' ? -1 : 1))
                    }
                  }}
                  className={`min-h-24 border-b border-r p-2 text-left align-top hover:bg-muted/40 aria-selected:bg-primary/10 ${day.getMonth() !== view.getMonth() ? 'bg-muted/30 text-muted-foreground' : ''}`}
                >
                  <span className="text-xs">{day.getDate()}</span>
                  {events
                    .filter((event) => isSameDay(event.date, day))
                    .map((event) => (
                      <span
                        key={event.id}
                        className="mt-1 block truncate rounded bg-background/90 p-1 text-[10px] text-foreground"
                      >
                        {event.title}
                      </span>
                    ))}
                </button>
              ))}
            </div>
          ))}
        </div>
      )}
    </section>
  )
}
